1	package vault
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14	)
15	
16	// Snapshot is an immutable record of every name mapping in the repository at
17	// creation time. It only references existing content objects; no artifact
18	// bytes are copied.
19	type Snapshot struct {
20		Name    string           `json:"name"`
21		Entries map[string]Entry `json:"entries"`
22	}
23	
24	// SnapshotInfo summarizes a saved snapshot for listing.
25	type SnapshotInfo struct {
26		Name  string
27		Count int
28	}
29	
30	// CreateSnapshot records the current name mapping under the given snapshot
31	// name. It first requires the current mapping itself to be complete and
32	// unambiguous — the index is loaded with the same strict rules verify and gc
33	// apply (a bare null, an empty {}, a missing or null entries mapping, a
34	// non-object entries value, a truncated document, trailing content, or any
35	// duplicate key at any level — including a name repeated through Unicode
36	// escapes — is corruption, while a genuine {"entries":{}} is a legitimate
37	// empty repository), and every record is keyed by its recorded name and
38	// carries a legal name, a 64-character lowercase-hex digest, and a
39	// non-negative size. Validation runs before anything is written and is
40	// all-or-nothing: one bad record rejects the whole operation; bad entries are
41	// never skipped to leave a seemingly usable partial snapshot.
42	//
43	// Index problems are reported as "cannot create snapshot <name>: current
44	// index is corrupt: <reason>", with the duplicated key or offending artifact
45	// named, distinct from an illegal snapshot name and from an existing snapshot
46	// (snapshot %q already exists). On failure no snapshot record is created —
47	// saveSnapshot itself writes a temporary file and renames it into place — and
48	// the index's original bytes, existing snapshots, and content objects are
49	// untouched. The snapshot records metadata only and references existing
50	// objects; content is re-verified by restore and export under their existing
51	// rules.
52	func (s *Store) CreateSnapshot(name string) (Snapshot, error) {
53		if err := validateName(name); err != nil {
54			return Snapshot{}, err
55		}
56		var snap Snapshot
57		err := s.withLock(true, func() error {
58			if err := s.initLocked(); err != nil {
59				return err
60			}
61			idx, err := s.loadStrict()
62			if err != nil {
63				return fmt.Errorf("cannot create snapshot %q: %w", name, err)
64			}
65			// Validate every record before writing anything, in sorted order so the
66			// first reported bad entry is deterministic. One bad record rejects the
67			// whole snapshot; the mapping is never filtered into a partial backup.
68			keys := make([]string, 0, len(idx.Entries))
69			for key := range idx.Entries {
70				keys = append(keys, key)
71			}
72			sort.Strings(keys)
73			for _, key := range keys {
74				if err := validateEntryRecord(key, idx.Entries[key]); err != nil {
75					return fmt.Errorf("cannot create snapshot %q: current index is corrupt: %w", name, err)
76				}
77			}
78			path := s.snapshotPath(name)
79			if _, err := os.Stat(path); err == nil {
80				return fmt.Errorf("snapshot %q already exists", name)
81			} else if !errors.Is(err, os.ErrNotExist) {
82				return err
83			}
84			snap = Snapshot{Name: name, Entries: idx.Entries}
85			return s.saveSnapshot(path, snap)
86		})
87		if err != nil {
88			return Snapshot{}, err
89		}
90		return snap, nil
91	}
92	
93	// ListSnapshots returns every saved snapshot, sorted by its complete snapshot
94	// name, with the number of artifact records in its entries mapping.
95	//
96	// A snapshot is listed only after its record proves complete and legal: it is
97	// validated exactly the way RestoreSnapshot validates the record it restores
98	// (see decodeSnapshotRecord) — a single JSON object whose recorded name
99	// equals its filing name in full ("releases/stable", never just "stable"),
100	// with a present, object-valued entries mapping spelled exactly "entries"
101	// ({} is a legitimate empty snapshot; a missing or null entries field is
102	// corruption, and so is any case-variant spelling such as "Entries", alone
103	// or beside the standard field) containing only
104	// valid artifact records. The content objects the entries reference are not
105	// read or checked; listing depends on neither the objects nor the health of
106	// the current name mapping.
107	//
108	// One damaged, unreadable, or misplaced record fails the whole operation:
109	// the error names the complete snapshot and what is wrong with it and no
110	// SnapshotInfo is returned, so callers never see a partial list or read a
111	// name or count off a corrupt record. A repository whose snapshots directory
112	// does not exist yet simply has no snapshots and yields an empty list; a
113	// record read failing with "not exist" once the directory walk has started
114	// is reported rather than treated as absence. Non-snapshot files (temporary
115	// files and anything not ending in .json) are ignored. Listing never
116	// modifies the current mapping, any snapshot record, or any content object.
117	func (s *Store) ListSnapshots() ([]SnapshotInfo, error) {
118		infos := []SnapshotInfo{}
119		err := s.withLock(false, func() error {
120			return s.walkSnapshotRecords(func(name string, snap Snapshot) error {
121				infos = append(infos, SnapshotInfo{Name: name, Count: len(snap.Entries)})
122				return nil
123			})
124		})
125		if err != nil {
126			return nil, err
127		}
128		sort.Slice(infos, func(i, j int) bool { return infos[i].Name < infos[j].Name })
129		return infos, nil
130	}
131	
132	// walkSnapshotRecords enumerates the snapshot records filed under snapshots/
133	// and invokes fn with each record's complete snapshot name and its parsed,
134	// fully validated contents (see decodeSnapshotRecord). It is the single
135	// enumeration used by read-only operations that must see exactly the records
136	// restore would accept — listing and reference collection alike.
137	//
138	// A missing snapshots directory means no snapshots exist and is not an error.
139	// Every other problem aborts the walk: a symlinked or non-directory snapshots
140	// path, a symlink or other non-regular file beneath it, a .json file whose
141	// location does not encode a legal snapshot name, a record that cannot be
142	// read (including one that disappears mid-walk), and any malformed or
143	// incomplete record. Errors name the complete snapshot when its location is
144	// known. Files without a .json suffix (temporary files and other stray data)
145	// are skipped.
146	func (s *Store) walkSnapshotRecords(fn func(name string, snap Snapshot) error) error {
147		dir := s.snapshotsDir()
148		info, err := os.Lstat(dir)
149		switch {
150		case errors.Is(err, os.ErrNotExist):
151			return nil
152		case err != nil:
153			return fmt.Errorf("cannot inspect snapshots directory: %w", err)
154		case info.Mode()&os.ModeSymlink != 0:
155			return fmt.Errorf("snapshots path %q is a symbolic link", dir)
156		case !info.IsDir():
157			return fmt.Errorf("snapshots path %q is not a directory", dir)
158		}
159		return filepath.WalkDir(dir, func(path string, d fs.DirEntry, walkErr error) error {
160			if walkErr != nil {
161				// The directory entry was seen but the path can no longer be
162				// accessed: a vanished record is a read failure, not an empty set.
163				return walkErr
164			}
165			if d.IsDir() {
166				return nil
167			}
168			rel, err := filepath.Rel(dir, path)
169			if err != nil {
170				return err
171			}
172			isRecord := strings.HasSuffix(d.Name(), ".json")
173			// Name the snapshot when the offending path occupies a record slot;
174			// other stray entries are identified by path.
175			if d.Type()&os.ModeSymlink != 0 {
176				if isRecord {
177					name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
178					return fmt.Errorf("snapshot %q is a symbolic link", name)
179				}
180				return fmt.Errorf("snapshots contain symbolic link %q", path)
181			}
182			if !d.Type().IsRegular() {
183				if isRecord {
184					name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
185					return fmt.Errorf("snapshot %q is not a regular file", name)
186				}
187				return fmt.Errorf("snapshots contain non-regular file %q", path)
188			}
189			if !isRecord {
190				return nil
191			}
192			name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
193			if err := validateName(name); err != nil {
194				return fmt.Errorf("snapshot record %q does not map to a valid snapshot name: %w", path, err)
195			}
196			data, err := os.ReadFile(path)
197			if err != nil {
198				return fmt.Errorf("snapshot %q cannot be read: %w", name, err)
199			}
200			snap, err := decodeSnapshotRecord(data, name)
201			if err != nil {
202				return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
203			}
204			return fn(name, snap)
205		})
206	}
207	
208	// RestoreSnapshot replaces the current name mapping with the snapshot's
209	// recorded mapping in a single atomic index write. The current index is never
210	// read, so restore works even when it is corrupted. The selected snapshot
211	// record must be a complete, well-formed document whose recorded name equals
212	// the selected snapshot name in full (a record nested under "releases/stable"
213	// must itself say "releases/stable", never just "stable") and whose entries
214	// mapping is present, spelled exactly "entries" (any case-variant spelling
215	// such as "Entries" is corruption, alone or beside the standard field), and
216	// an object ({} is a legitimate empty snapshot; a missing, null, or
217	// non-object entries field is corruption, never an empty mapping). Every referenced object is checked for existence, size, and
218	// SHA-256 before the mapping is swapped; any failure leaves the current
219	// mapping's bytes and all snapshots and objects untouched, even when the
220	// current mapping itself is already corrupted.
221	func (s *Store) RestoreSnapshot(name string) error {
222		if err := validateName(name); err != nil {
223			return err
224		}
225		return s.withLock(true, func() error {
226			if err := s.initLocked(); err != nil {
227				return err
228			}
229			snap, err := s.loadSnapshotRecord(name)
230			if err != nil {
231				return err
232			}
233			for _, entry := range snap.Entries {
234				if err := s.verifyObject(entry); err != nil {
235					return fmt.Errorf("cannot restore snapshot %q: object for %q: %w", name, entry.Name, err)
236				}
237			}
238			return s.save(index{Entries: snap.Entries})
239		})
240	}
241	
242	// decodeSnapshotRecord parses one snapshot record without touching the
243	// repository. wantName is the full snapshot name the record is selected or
244	// filed under and must record verbatim.
245	//
246	// A valid record is exactly one JSON object — never the bare null — with no
247	// duplicate or unknown fields and no trailing data, carrying:
248	//
249	//   - "name": present and a string equal to wantName, including every level of
250	//     a multi-level name; a missing, wrong-type, or merely-suffixed name
251	//     (record "stable" under "releases/stable") is refused;
252	//   - "entries": present, spelled exactly "entries", and a JSON object. {} is
253	//     a legitimate empty mapping; a missing field, a null, an array, or any
254	//     non-object value is corruption rather than zero entries. A field whose
255	//     decoded name matches "entries" only case-insensitively ("Entries",
256	//     "ENTRIES", ...) is corruption whether it appears alone or beside the
257	//     standard field, in either order, with identical or different content,
258	//     empty or not: encoding/json binds struct fields case-insensitively, so
259	//     without the check the variant would silently populate the mapping — and
260	//     when both spellings appear, whichever came last would silently replace
261	//     the other, dropping artifact references or installing an empty mapping.
262	//     Field names are compared after JSON string decoding, so "entries"
263	//     written through Unicode escapes stays valid while an escape decoding to
264	//     a case variant is rejected. The rule applies only to the top-level
265	//     mapping field; artifact names remain case-sensitive.
266	//
267	// Every entry is then checked with validateEntryRecord. The errors
268	// distinguish a missing entries mapping, a mismatching recorded name, and a
269	// malformed document so callers can tell record corruption apart from a
270	// snapshot that simply does not exist (that distinction is made by the
271	// caller, which checks the file before reading it).
272	func decodeSnapshotRecord(data []byte, wantName string) (Snapshot, error) {
273		if err := rejectDuplicateKeys(data); err != nil {
274			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
275		}
276		// The document must be a JSON object: a bare null, array, or primitive is
277		// a malformed record, never an empty snapshot.
278		if trimmed := bytes.TrimSpace(data); len(trimmed) == 0 || trimmed[0] != '{' {
279			return Snapshot{}, errors.New("malformed record: expected a JSON object with name and entries")
280		}
281		var raw struct {
282			Name    *string          `json:"name"`
283			Entries *json.RawMessage `json:"entries"`
284		}
285		dec := json.NewDecoder(bytes.NewReader(data))
286		dec.DisallowUnknownFields()
287		if err := dec.Decode(&raw); err != nil {
288			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
289		}
290		if tok, err := dec.Token(); err != io.EOF {
291			if err == nil {
292				return Snapshot{}, fmt.Errorf("malformed record: unexpected trailing content after the snapshot object (%v)", tok)
293			}
294			return Snapshot{}, fmt.Errorf("malformed record: %w", err)
295		}
296		// A field that spells the entries mapping with different casing
297		// ("Entries", "ENTRIES", ...) would be silently bound to it by
298		// encoding/json — and would silently overwrite or be overwritten by the
299		// standard spelling when both appear — so any such field is corruption,
300		// regardless of order, content, or emptiness.
301		if err := rejectEntriesCaseVariants(data); err != nil {
302			return Snapshot{}, err
303		}
304		if raw.Name == nil {
305			return Snapshot{}, errors.New("malformed record: missing snapshot name")
306		}
307		if *raw.Name != wantName {
308			return Snapshot{}, fmt.Errorf("recorded name %q does not match snapshot %q", *raw.Name, wantName)
309		}
310		if raw.Entries == nil {
311			return Snapshot{}, errors.New("record is missing its entries mapping")
312		}
313		entriesJSON := *raw.Entries
314		if string(bytes.TrimSpace(entriesJSON)) == "null" {
315			return Snapshot{}, errors.New("record is missing its entries mapping")
316		}
317		var entries map[string]Entry
318		if err := json.Unmarshal(entriesJSON, &entries); err != nil {
319			return Snapshot{}, fmt.Errorf("entries mapping is malformed: %w", err)
320		}
321		if entries == nil {
322			return Snapshot{}, errors.New("record is missing its entries mapping")
323		}
324		for key, entry := range entries {
325			if err := validateEntryRecord(key, entry); err != nil {
326				return Snapshot{}, err
327			}
328		}
329		return Snapshot{Name: *raw.Name, Entries: entries}, nil
330	}
331	
332	func (s *Store) saveSnapshot(path string, snap Snapshot) error {
333		data, err := json.MarshalIndent(snap, "", "  ")
334		if err != nil {
335			return err
336		}
337		data = append(data, '\n')
338		if err := s.ensureSnapshotParent(path); err != nil {
339			return err
340		}
341		dir := filepath.Dir(path)
342		tmp, err := os.CreateTemp(dir, ".snapshot-*")
343		if err != nil {
344			return err
345		}
346		tmpName := tmp.Name()
347		defer os.Remove(tmpName)
348		if _, err := tmp.Write(data); err != nil {
349			tmp.Close()
350			return err
351		}
352		if err := tmp.Close(); err != nil {
353			return err
354		}
355		return os.Rename(tmpName, path)
356	}
357	
358	// ensureSnapshotParent creates the parent directories of a snapshot record one
359	// component at a time, refusing to follow symbolic links. Without this a nested
360	// snapshot name such as "evil/x" could be redirected through a pre-created
361	// snapshots/evil symlink to write outside the repository.
362	func (s *Store) ensureSnapshotParent(path string) error {
363		base := s.snapshotsDir()
364		rel, err := filepath.Rel(base, filepath.Dir(path))
365		if err != nil {
366			return err
367		}
368		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
369			return errors.New("snapshot path escapes the snapshots directory")
370		}
371		// The base directory itself must exist and be a real directory, even for a
372		// top-level snapshot (a freshly initialized repository has no snapshots/).
373		cur := base
374		if err := ensureRealDir(cur); err != nil {
375			return err
376		}
377		if rel == "." {
378			return nil
379		}
380		for _, component := range strings.Split(rel, string(filepath.Separator)) {
381			next := filepath.Join(cur, component)
382			if err := ensureRealDir(next); err != nil {
383				return err
384			}
385			cur = next
386		}
387		return nil
388	}
389	
390	// ensureRealDir makes sure path is a real directory, creating it if absent,
391	// and refuses an existing symlink or non-directory.
392	func ensureRealDir(path string) error {
393		info, err := os.Lstat(path)
394		switch {
395		case errors.Is(err, os.ErrNotExist):
396			if err := os.Mkdir(path, 0o755); err != nil && !errors.Is(err, os.ErrExist) {
397				return err
398			}
399			info, err = os.Lstat(path)
400			if err != nil {
401				return err
402			}
403		case err != nil:
404			return err
405		}
406		if info.Mode()&os.ModeSymlink != 0 {
407			return fmt.Errorf("repository path %q is a symbolic link", path)
408		}
409		if !info.IsDir() {
410			return fmt.Errorf("repository path %q is not a directory", path)
411		}
412		return nil
413	}
414	
415	func (s *Store) snapshotsDir() string { return filepath.Join(s.root, "snapshots") }
416	
417	func (s *Store) snapshotPath(name string) string {
418		return filepath.Join(s.snapshotsDir(), filepath.FromSlash(name)+".json")
419	}
420	
421	func isDigest(digest string) bool {
422		if len(digest) != 64 {
423			return false
424		}
425		for _, c := range digest {
426			if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
427				return false
428			}
429		}
430		return true
431	}
