1	package vault
2	
3	import (
4		"bufio"
5		"crypto/sha256"
6		"encoding/base64"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io"
12		"os"
13		"path/filepath"
14		"reflect"
15		"sort"
16	)
17	
18	// ExportResult summarizes a successful snapshot export.
19	type ExportResult struct {
20		Name    string
21		Entries int
22		Objects int
23	}
24	
25	// ImportResult summarizes a successful snapshot import.
26	type ImportResult struct {
27		Name       string
28		Entries    int
29		NewObjects int
30	}
31	
32	// ExportSnapshot writes the named snapshot, together with the content objects
33	// it needs, to output as a portable package.
34	//
35	// Without a base the package is complete: every referenced object is carried,
36	// and a digest shared by several entries is carried once. With base set to the
37	// name of another snapshot in the same repository, the package still records
38	// the target's complete mapping but only carries objects the base does not
39	// reference; an importer can only apply it on top of an identical base.
40	//
41	// Every object the target references is re-read and checked for recorded size
42	// and SHA-256, including objects omitted from a delta, so a corrupt snapshot
43	// record or a missing/damaged object never produces a successful package.
44	//
45	// The output location is held to the same rules as a download: it must be
46	// outside the source repository (judged on actual locations, through
47	// symlinks, and before the file exists), its parent directory must already
48	// exist, an existing output must be a regular file that is not hard-linked to
49	// any index, snapshot record, lock file, or content object, and the package
50	// is committed through a descriptor pinned to the resolved parent directory,
51	// so a parent swapped for a symlink into the repository while the export runs
52	// is detected at commit time and can never redirect the package onto a
53	// repository file. The package is streamed to a temporary file in that
54	// directory — each object's bytes are read, verified, and encoded in chunks,
55	// never held in memory — before an atomic rename: a failed export never
56	// creates or alters the output file, and the extra memory an export needs
57	// does not grow with any object's size or the total carried bytes.
58	func (s *Store) ExportSnapshot(name, base, output string) (ExportResult, error) {
59		if err := validateName(name); err != nil {
60			return ExportResult{}, err
61		}
62		if base != "" {
63			if err := validateName(base); err != nil {
64				return ExportResult{}, err
65			}
66		}
67		if output == "" {
68			return ExportResult{}, errors.New("output is required")
69		}
70		// Export reads an existing, initialized repository; it never creates one.
71		// The root and index are checked before taking the lock (withLockOpts
72		// passes createRoot=false so even the root directory is not materialized),
73		// and re-checked while holding the lock.
74		rootInfo, err := os.Stat(s.root)
75		switch {
76		case errors.Is(err, os.ErrNotExist):
77			return ExportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
78		case err != nil:
79			return ExportResult{}, err
80		case !rootInfo.IsDir():
81			return ExportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
82		}
83		if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
84			return ExportResult{}, fmt.Errorf("repository %q is not initialized; run init first", s.root)
85		} else if err != nil {
86			return ExportResult{}, err
87		}
88		var result ExportResult
89		err = s.withLockOpts(true, false, func() error {
90			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
91				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
92			} else if err != nil {
93				return err
94			}
95			// Validate the destination before reading any object or staging a
96			// temporary file, and hold the pinned parent directory until commit.
97			absOut, mode, pin, err := s.checkOutputSafe(output)
98			if err != nil {
99				return err
100			}
101			defer pin.Close()
102	
103			target, err := s.loadSnapshotRecord(name)
104			if err != nil {
105				return err
106			}
107			var baseSnap *Snapshot
108			if base != "" {
109				loaded, err := s.loadSnapshotRecord(base)
110				if err != nil {
111					return fmt.Errorf("cannot use base snapshot: %w", err)
112				}
113				baseSnap = &loaded
114			}
115	
116			// Verify every object the target references, reading each once. This
117			// includes objects the delta omits because the base references them:
118			// certifying the delta requires those to be intact too. Only objects
119			// the base does not reference are carried. Digests are processed in
120			// sorted order so the package layout and any failure message are
121			// deterministic.
122			carry := digestsReferenced(target.Entries)
123			if baseSnap != nil {
124				for digest := range digestsReferenced(baseSnap.Entries) {
125					delete(carry, digest)
126				}
127			}
128			objects, err := s.writePackage(pin, absOut, mode, name, target, baseSnap, carry)
129			if err != nil {
130				return err
131			}
132			result = ExportResult{Name: name, Entries: len(target.Entries), Objects: objects}
133			return nil
134		})
135		if err != nil {
136			return ExportResult{}, err
137		}
138		return result, nil
139	}
140	
141	// writePackage stages the snapshot package as a complete temporary file
142	// inside the pinned parent directory and commits it via Store.commitOutput,
143	// which revalidates the destination immediately before the atomic rename. The
144	// document is streamed to the temporary file while each referenced object is
145	// verified, so neither object content nor the package text is ever held in
146	// memory. On any failure the temporary file is removed and an existing output
147	// is never touched. It returns the number of carried objects.
148	func (s *Store) writePackage(pin *parentPin, absOut string, mode os.FileMode, name string, target Snapshot, base *Snapshot, carry map[string]struct{}) (int, error) {
149		tmp, tmpBase, err := createTempIn(pin, ".package-")
150		if err != nil {
151			return 0, fmt.Errorf("cannot create temporary file for output: %w", err)
152		}
153		committed := false
154		defer func() {
155			if !committed {
156				removeTempIn(pin, tmpBase)
157			}
158		}()
159		if err := tmp.Chmod(mode); err != nil {
160			tmp.Close()
161			return 0, fmt.Errorf("cannot prepare output file: %w", err)
162		}
163		objects, err := s.streamPackage(tmp, absOut, name, target, base, carry)
164		if err != nil {
165			tmp.Close()
166			return 0, err
167		}
168		if err := tmp.Sync(); err != nil {
169			tmp.Close()
170			return 0, fmt.Errorf("cannot write output %q: %w", absOut, err)
171		}
172		if err := tmp.Close(); err != nil {
173			return 0, fmt.Errorf("cannot write output %q: %w", absOut, err)
174		}
175		if err := s.commitOutput(pin, tmpBase, absOut); err != nil {
176			return 0, err
177		}
178		committed = true
179		_ = syncDirectory(pin.f)
180		return objects, nil
181	}
182	
183	// streamPackage writes the snapshot package to out as one indented JSON
184	// document, byte-identical to marshalPackage over the equivalent in-memory
185	// representation, while reading every referenced object exactly once in
186	// chunks. Objects in the carry set are base64-encoded into the document as
187	// they are verified; objects the delta omits are verified with the same
188	// strictness without being written. Content is never buffered, so memory use
189	// stays independent of object and package size. It returns the number of
190	// carried objects.
191	func (s *Store) streamPackage(out *os.File, absOut, name string, target Snapshot, base *Snapshot, carry map[string]struct{}) (int, error) {
192		snapshotJSON, err := json.MarshalIndent(target, "  ", "  ")
193		if err != nil {
194			return 0, err
195		}
196		var baseJSON []byte
197		if base != nil {
198			baseJSON, err = json.MarshalIndent(*base, "  ", "  ")
199			if err != nil {
200				return 0, err
201			}
202		}
203	
204		w := bufio.NewWriter(out)
205		ew := &errWriter{w: w}
206		ew.writeString("{\n  \"format\": ")
207		ew.writeString(jsonString(packageFormat))
208		fmt.Fprintf(ew, ",\n  \"version\": %d,\n  \"snapshot\": ", packageVersion)
209		ew.Write(snapshotJSON)
210		if base != nil {
211			ew.writeString(",\n  \"base\": ")
212			ew.Write(baseJSON)
213		}
214		ew.writeString(",\n  \"objects\": [")
215	
216		objects := 0
217		for _, digest := range sortedDigests(target.Entries) {
218			if _, carried := carry[digest]; !carried {
219				// Omitted from a delta package: verified in full, not carried.
220				if _, err := s.streamVerifiedObject(digest, target.Entries, nil); err != nil {
221					return 0, fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, err)
222				}
223				continue
224			}
225			if ew.err != nil {
226				return 0, fmt.Errorf("cannot write output %q: %w", absOut, ew.err)
227			}
228			if objects > 0 {
229				ew.writeString(",")
230			}
231			// The size field precedes the data, so the recorded size is written
232			// before the content is measured; streamVerifiedObject then confirms
233			// the actual byte count against every referencing record before
234			// anything is committed, so a lying record still fails the export.
235			fmt.Fprintf(ew, "\n    {\n      \"digest\": \"%s\",\n      \"size\": %d,\n      \"data\": \"",
236				digest, recordedSize(target.Entries, digest))
237			enc := base64.NewEncoder(base64.StdEncoding, ew)
238			_, verr := s.streamVerifiedObject(digest, target.Entries, enc)
239			cerr := enc.Close()
240			if ew.err != nil {
241				return 0, fmt.Errorf("cannot write output %q: %w", absOut, ew.err)
242			}
243			if verr != nil {
244				return 0, fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, verr)
245			}
246			if cerr != nil {
247				return 0, fmt.Errorf("cannot write output %q: %w", absOut, cerr)
248			}
249			ew.writeString("\"\n    }")
250			objects++
251		}
252		if objects > 0 {
253			ew.writeString("\n  ")
254		}
255		ew.writeString("]\n}\n")
256		if ew.err != nil {
257			return 0, fmt.Errorf("cannot write output %q: %w", absOut, ew.err)
258		}
259		if err := w.Flush(); err != nil {
260			return 0, fmt.Errorf("cannot write output %q: %w", absOut, err)
261		}
262		return objects, nil
263	}
264	
265	// errWriter records the first write error so the streaming writer can report
266	// an output failure instead of mistaking it for object corruption.
267	type errWriter struct {
268		w   *bufio.Writer
269		err error
270	}
271	
272	func (ew *errWriter) Write(p []byte) (int, error) {
273		if ew.err != nil {
274			return 0, ew.err
275		}
276		n, err := ew.w.Write(p)
277		if err != nil {
278			ew.err = err
279		}
280		return n, err
281	}
282	
283	func (ew *errWriter) writeString(s string) {
284		if ew.err != nil {
285			return
286		}
287		if _, err := ew.w.WriteString(s); err != nil {
288			ew.err = err
289		}
290	}
291	
292	// jsonString renders s as a JSON string literal exactly as encoding/json
293	// does, so hand-written fragments match the marshaled parts of the document.
294	func jsonString(s string) string {
295		data, err := json.Marshal(s)
296		if err != nil {
297			panic(err) // a string always marshals
298		}
299		return string(data)
300	}
301	
302	// recordedSize returns the size any entry referencing digest records for it.
303	// Carried digests are always referenced, and streamVerifiedObject confirms
304	// the recorded size against the actual byte count before the export commits.
305	func recordedSize(entries map[string]Entry, digest string) int64 {
306		for _, entry := range entries {
307			if entry.Digest == digest {
308				return entry.Size
309			}
310		}
311		return 0
312	}
313	
314	// streamVerifiedObject reads the content object filed under digest in chunks,
315	// requiring it to be a regular file (never a symlink or other special file)
316	// whose actual byte count and SHA-256 match digest and the size every
317	// referencing entry records for it. When sink is non-nil the bytes are
318	// written to sink as they are read; either way content is never held in
319	// memory. It returns the true byte count.
320	func (s *Store) streamVerifiedObject(digest string, entries map[string]Entry, sink io.Writer) (int64, error) {
321		path := s.objectPath(digest)
322		info, err := os.Lstat(path)
323		if err != nil {
324			return 0, err
325		}
326		if info.Mode()&os.ModeSymlink != 0 {
327			return 0, errors.New("object path is a symbolic link")
328		}
329		if !info.Mode().IsRegular() {
330			return 0, errors.New("object path is not a regular file")
331		}
332		file, err := os.Open(path)
333		if err != nil {
334			return 0, err
335		}
336		hash := sha256.New()
337		var w io.Writer = hash
338		if sink != nil {
339			w = io.MultiWriter(hash, sink)
340		}
341		size, copyErr := io.Copy(w, file)
342		closeErr := file.Close()
343		if copyErr != nil {
344			return 0, copyErr
345		}
346		if closeErr != nil {
347			return 0, closeErr
348		}
349		if actual := hex.EncodeToString(hash.Sum(nil)); actual != digest {
350			return 0, fmt.Errorf("content checksum is %s", actual)
351		}
352		// Every entry referencing this digest must agree on the size; a content
353		// hash fixes the byte count, so a disagreement is a corrupt record.
354		for _, entry := range entries {
355			if entry.Digest == digest && size != entry.Size {
356				return 0, fmt.Errorf("content is %d bytes, record for %q says %d", size, entry.Name, entry.Size)
357			}
358		}
359		return size, nil
360	}
361	
362	// ImportSnapshot imports a snapshot package produced by ExportSnapshot into an
363	// initialized repository.
364	//
365	// Import only adds the package's snapshot and any missing content objects; it
366	// never changes the current name mapping or any existing snapshot or object.
367	// A delta package is accepted only when the destination already contains a
368	// snapshot with the base name and byte-identical entry metadata, and every
369	// object the delta omits is present and intact. Healthy objects already in the
370	// destination are reused; re-importing a package whose snapshot is already
371	// present with identical metadata succeeds without creating a second copy. A
372	// same-named snapshot with different metadata is refused.
373	//
374	// Every target record's size must equal the actual byte count of the content
375	// its digest names, checked separately for each name that references it.
376	// Carried content is measured while the package is decoded; content a delta
377	// omits is measured from the destination (after the matching base has proven
378	// it present and healthy) before anything is written. A record that keeps a
379	// valid digest but declares another size therefore rejects the entire
380	// package — other correct records and other correct new objects included —
381	// and names the target snapshot, artifact, digest, recorded size, and actual
382	// byte count as record corruption rather than a checksum failure.
383	//
384	// All validation and reuse happens before anything is written, so a rejected
385	// package adds no object, snapshot, or temporary file. New objects then land
386	// as complete files via temp-file-and-rename, and the snapshot record is
387	// renamed into place only after every object the mapping references has been
388	// verified. Consequently only an actual crash or write failure between those
389	// two commits can leave an unreferenced complete object, which a later gc
390	// removes and a retry completes; a partially imported snapshot can never be
391	// observed.
392	func (s *Store) ImportSnapshot(file string) (ImportResult, error) {
393		if file == "" {
394			return ImportResult{}, errors.New("file is required")
395		}
396		data, err := os.ReadFile(file)
397		if err != nil {
398			return ImportResult{}, err
399		}
400		pkg, err := decodePackage(data)
401		if err != nil {
402			return ImportResult{}, err
403		}
404		// Import targets an initialized repository; it never creates one the way
405		// mutating artifact commands do.
406		rootInfo, err := os.Stat(s.root)
407		switch {
408		case errors.Is(err, os.ErrNotExist):
409			return ImportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
410		case err != nil:
411			return ImportResult{}, err
412		case !rootInfo.IsDir():
413			return ImportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
414		}
415		var result ImportResult
416		err = s.withLock(true, func() error {
417			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
418				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
419			} else if err != nil {
420				return err
421			}
422			if err := rejectLinkedDirs(s.root); err != nil {
423				return err
424			}
425	
426			// A delta must sit on an exactly matching base: same snapshot name and
427			// identical entry metadata. A merely same-named snapshot, or objects
428			// that happen to share digests, is not a base.
429			if pkg.Base != nil {
430				existing, err := s.loadSnapshotRecord(pkg.Base.Name)
431				if err != nil {
432					return fmt.Errorf("delta base snapshot %q is unavailable: %w", pkg.Base.Name, err)
433				}
434				if !snapshotsEqual(existing, *pkg.Base) {
435					return fmt.Errorf("delta base snapshot %q does not match the package base", pkg.Base.Name)
436				}
437				if err := s.verifyReferencedObjects(pkg.Base.Name, existing.Entries); err != nil {
438					return fmt.Errorf("delta base snapshot %q is not fully present: %w", pkg.Base.Name, err)
439				}
440			}
441	
442			// Record sizes are validated against carried payloads when the package
443			// is decoded. Objects a delta omits are not carried, so their sizes are
444			// measured from the destination here — while the matching base has just
445			// proven them present and healthy — before anything is staged. A target
446			// entry that keeps a valid digest but declares another byte count is a
447			// corrupt record: it rejects the whole import, including every other
448			// correct entry and any new object the package carries, so a failed
449			// import can never install even one unreferenced content object.
450			if err := s.verifyOmittedEntrySizes(pkg); err != nil {
451				return err
452			}
453	
454			// A same-named destination snapshot is either identical metadata or a
455			// collision. A collision is refused before anything is staged.
456			targetPath := s.snapshotPath(pkg.Snapshot.Name)
457			identicalSnapshot := false
458			if existing, statErr := os.Lstat(targetPath); statErr == nil {
459				if existing.Mode()&os.ModeSymlink != 0 {
460					return fmt.Errorf("snapshot path %q is a symbolic link", targetPath)
461				}
462				current, err := s.loadSnapshotRecord(pkg.Snapshot.Name)
463				if err != nil {
464					return fmt.Errorf("snapshot %q already exists and is unusable: %w", pkg.Snapshot.Name, err)
465				}
466				if !snapshotsEqual(current, pkg.Snapshot) {
467					return fmt.Errorf("snapshot %q already exists with different metadata; refusing to overwrite", pkg.Snapshot.Name)
468				}
469				identicalSnapshot = true
470				// Fast path: everything the published snapshot needs is already
471				// present and healthy, so the import is a no-op.
472				if s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries) == nil {
473					result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: 0}
474					return nil
475				}
476				// Otherwise fall through: a carried object that is merely missing
477				// can be staged to complete an earlier interrupted import, while a
478				// damaged existing object still aborts below.
479			} else if !errors.Is(statErr, os.ErrNotExist) {
480				return statErr
481			}
482	
483			objects, err := pkg.materialize()
484			if err != nil {
485				return err
486			}
487	
488			// Phase 1, no writes: classify every carried object. Existing files
489			// must be healthy and are reused; a damaged one aborts the import and
490			// is reported by digest.
491			toAdd := make([]objectContent, 0, len(objects))
492			for _, obj := range objects {
493				path := s.objectPath(obj.digest)
494				info, err := os.Lstat(path)
495				switch {
496				case err == nil:
497					if info.Mode()&os.ModeSymlink != 0 {
498						return fmt.Errorf("object %s: object path is a symbolic link", obj.digest)
499					}
500					if !info.Mode().IsRegular() {
501						return fmt.Errorf("object %s: object path is not a regular file", obj.digest)
502					}
503					// Record sizes were validated against the carried payload when
504					// the package was decoded; only the existing object's own type
505					// and checksum still need to prove healthy before reuse.
506					if _, _, err := s.readHealthyObject(obj.digest); err != nil {
507						return fmt.Errorf("object %s already present but damaged: %w", obj.digest, err)
508					}
509				case errors.Is(err, os.ErrNotExist):
510					toAdd = append(toAdd, obj)
511				default:
512					return err
513				}
514			}
515	
516			// Phase 2: stage missing objects as complete, content-addressed files.
517			// A failure here leaves only unreferenced complete objects behind; a
518			// retry reuses them and finishes the import.
519			for _, obj := range toAdd {
520				if err := s.stageObject(obj.digest, obj.content); err != nil {
521					return err
522				}
523			}
524	
525			// Phase 3: the published mapping must be fully restorable. This covers
526			// reused objects, newly staged ones, and everything omitted by a delta.
527			if err := s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries); err != nil {
528				return err
529			}
530	
531			// Phase 4: publish the snapshot record last (unless an identical one is
532			// already published). This rename is the commit point; before it a new
533			// imported snapshot simply does not exist.
534			if !identicalSnapshot {
535				if err := s.saveSnapshot(targetPath, pkg.Snapshot); err != nil {
536					return err
537				}
538			}
539			result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: len(toAdd)}
540			return nil
541		})
542		if err != nil {
543			return ImportResult{}, err
544		}
545		return result, nil
546	}
547	
548	// loadSnapshotRecord reads and fully validates one stored snapshot: the path
549	// must be a regular file (never a symlink), the document must be a single
550	// well-formed object, carry a present non-null entries mapping, record the
551	// same name it is filed under (in full), and contain only valid entry records.
552	func (s *Store) loadSnapshotRecord(name string) (Snapshot, error) {
553		path := s.snapshotPath(name)
554		info, err := os.Lstat(path)
555		if errors.Is(err, os.ErrNotExist) {
556			return Snapshot{}, fmt.Errorf("snapshot %q not found", name)
557		}
558		if err != nil {
559			return Snapshot{}, err
560		}
561		if info.Mode()&os.ModeSymlink != 0 {
562			return Snapshot{}, fmt.Errorf("snapshot %q is a symbolic link", name)
563		}
564		if !info.Mode().IsRegular() {
565			return Snapshot{}, fmt.Errorf("snapshot %q is not a regular file", name)
566		}
567		data, err := os.ReadFile(path)
568		if err != nil {
569			return Snapshot{}, err
570		}
571		snap, err := decodeSnapshotRecord(data, name)
572		if err != nil {
573			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
574		}
575		return snap, nil
576	}
577	
578	// verifyReferencedObjects checks each distinct referenced digest once against
579	// the stored object's size and SHA-256.
580	func (s *Store) verifyReferencedObjects(snapshotName string, entries map[string]Entry) error {
581		for _, digest := range sortedDigests(entries) {
582			if _, _, err := s.readVerifiedObject(digest, entries); err != nil {
583				return fmt.Errorf("object %s needed by snapshot %q: %w", digest, snapshotName, err)
584			}
585		}
586		return nil
587	}
588	
589	// verifyOmittedEntrySizes enforces the target record-size rule for content the
590	// package does not carry (the objects a delta omits, which the destination
591	// must already hold). Sizes for carried content were checked against the
592	// payloads while the package was decoded, so this looks only at digests absent
593	// from the carried set: each target entry naming one must record the exact
594	// byte count of the healthy object already in the destination. Every name is
595	// checked separately, in sorted order, since one digest may back several
596	// entries. The check reads and hashes content but writes nothing; it runs
597	// before any object is staged, so a mismatch rejects the whole package
598	// without leaving even a correct new object behind.
599	func (s *Store) verifyOmittedEntrySizes(pkg *Package) error {
600		carried := make(map[string]struct{}, len(pkg.Objects))
601		for _, obj := range pkg.Objects {
602			carried[obj.Digest] = struct{}{}
603		}
604		actualByDigest := map[string]int64{}
605		for _, name := range sortedEntryNames(pkg.Snapshot.Entries) {
606			entry := pkg.Snapshot.Entries[name]
607			if _, isCarried := carried[entry.Digest]; isCarried {
608				continue
609			}
610			actual, ok := actualByDigest[entry.Digest]
611			if !ok {
612				_, size, err := s.readHealthyObject(entry.Digest)
613				if err != nil {
614					// A missing or damaged destination object is content trouble,
615					// reported through the same path as the later full verification.
616					return fmt.Errorf("object %s needed by snapshot %q: %w", entry.Digest, pkg.Snapshot.Name, err)
617				}
618				actual = size
619				actualByDigest[entry.Digest] = size
620			}
621			if entry.Size != actual {
622				return newEntrySizeMismatchError(pkg.Snapshot.Name, entry.Name, entry.Digest, entry.Size, actual)
623			}
624		}
625		return nil
626	}
627	
628	// readHealthyObject loads the content object filed under digest, requiring it
629	// to be a regular file (never a symlink or other special file) whose full
630	// bytes hash to digest. It returns the bytes and their true byte count but
631	// makes no claim about any recorded size, so callers can distinguish a
632	// checksum failure from a record whose size disagrees with healthy content.
633	func (s *Store) readHealthyObject(digest string) ([]byte, int64, error) {
634		path := s.objectPath(digest)
635		info, err := os.Lstat(path)
636		if err != nil {
637			return nil, 0, err
638		}
639		if info.Mode()&os.ModeSymlink != 0 {
640			return nil, 0, errors.New("object path is a symbolic link")
641		}
642		if !info.Mode().IsRegular() {
643			return nil, 0, errors.New("object path is not a regular file")
644		}
645		content, err := os.ReadFile(path)
646		if err != nil {
647			return nil, 0, err
648		}
649		sum := sha256.Sum256(content)
650		if actual := hex.EncodeToString(sum[:]); actual != digest {
651			return nil, 0, fmt.Errorf("content checksum is %s", actual)
652		}
653		return content, int64(len(content)), nil
654	}
655	
656	// readVerifiedObject reads a content object and returns its bytes, confirming
657	// its SHA-256 digest and the size recorded for it in the given entries.
658	func (s *Store) readVerifiedObject(digest string, entries map[string]Entry) ([]byte, int64, error) {
659		content, size, err := s.readHealthyObject(digest)
660		if err != nil {
661			return nil, 0, err
662		}
663		// Every entry referencing this digest must agree on the size; a content
664		// hash fixes the byte count, so a disagreement is a corrupt record.
665		for _, entry := range entries {
666			if entry.Digest == digest && size != entry.Size {
667				return nil, 0, fmt.Errorf("content is %d bytes, record for %q says %d", size, entry.Name, entry.Size)
668			}
669		}
670		return content, size, nil
671	}
672	
673	// stageObject writes one missing object to a temp file and renames it into
674	// place. The content digest was verified when the package was decoded, so the
675	// final file is complete before it ever appears under its digest name.
676	func (s *Store) stageObject(digest string, content []byte) error {
677		tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".import-*")
678		if err != nil {
679			return err
680		}
681		tmpName := tmp.Name()
682		defer os.Remove(tmpName)
683		if _, err := tmp.Write(content); err != nil {
684			tmp.Close()
685			return fmt.Errorf("object %s: %w", digest, err)
686		}
687		if err := tmp.Close(); err != nil {
688			return fmt.Errorf("object %s: %w", digest, err)
689		}
690		if err := os.Rename(tmpName, s.objectPath(digest)); err != nil {
691			return fmt.Errorf("object %s: %w", digest, err)
692		}
693		return nil
694	}
695	
696	// rejectLinkedDirs makes sure an import can never stage files outside the
697	// repository through a replaced objects or snapshots directory.
698	func rejectLinkedDirs(root string) error {
699		for _, dir := range []string{filepath.Join(root, "objects"), filepath.Join(root, "snapshots")} {
700			if err := ensureRealDir(dir); err != nil {
701				return err
702			}
703		}
704		return nil
705	}
706	
707	// snapshotsEqual reports whether two snapshot records carry the same snapshot
708	// name and identical metadata for every entry.
709	func snapshotsEqual(a, b Snapshot) bool {
710		return reflect.DeepEqual(a.Entries, b.Entries) && a.Name == b.Name
711	}
712	
713	func sortedDigests(entries map[string]Entry) []string {
714		seen := map[string]struct{}{}
715		for _, entry := range entries {
716			seen[entry.Digest] = struct{}{}
717		}
718		out := make([]string, 0, len(seen))
719		for digest := range seen {
720			out = append(out, digest)
721		}
722		sort.Strings(out)
723		return out
724	}
