// decodePackageSnapshot decodes one snapshot record embedded in a package —
// the target snapshot or the delta base — and holds it to the same rule
// decodeSnapshotRecord applies to records on disk: the entries mapping must be
// spelled exactly "entries". encoding/json binds struct fields
// case-insensitively, so without this check an "Entries" field would silently
// populate the mapping, and a record carrying both spellings would keep only
// the later one — dropping artifact records or installing an empty mapping.
// Field names are compared after JSON string decoding, so the standard field
// written through Unicode escapes stays valid while an escape decoding to a
// case variant is rejected. The rule constrains only the record's mapping
// field; artifact names remain case-sensitive.
func decodePackageSnapshot(scope string, raw json.RawMessage) (Snapshot, error) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || string(trimmed) == "null" {
		// A missing or null record decodes to the zero record, exactly as a
		// direct struct decode produced, and fails validation below.
		trimmed = []byte("{}")
	}
	var snap Snapshot
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&snap); err != nil {
		return Snapshot{}, fmt.Errorf("invalid package: %s snapshot record is malformed: %w", scope, err)
